const rows = $input.all().map(i => i.json).filter(r => r && r.orderId);
const trigger = $('When Executed by Another Workflow').first().json;

if (rows.length === 0) {
  return [{ json: { isDuplicate: false, reason: 'no_previous_orders' } }];
}

rows.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
const newest = rows[0];

const minutesSinceLastOrder = (Date.now() - new Date(newest.timestamp).getTime()) / 60000;

let newItems = [];
let itemsParsedOk = true;
try { newItems = JSON.parse(trigger.items || '[]'); } catch (e) { itemsParsedOk = false; }
let lastItems = [];
lastItems = Array.isArray(newest.items) ? newest.items : [];

function normalize(items) {
  return items
    .map(i => (String(i.name || '').trim().toLowerCase()) + '::' + (i.qty || 1))
    .sort()
    .join('|');
}

const itemsMissing = newItems.length === 0;
const rawItemsMatch = normalize(newItems) === normalize(lastItems);
const itemsMatch = itemsMissing ? false : rawItemsMatch;

const withinWindow = minutesSinceLastOrder <= 30;

const isDuplicate = withinWindow || itemsMatch;

let reason = 'not_duplicate';
if (isDuplicate) {
  if (withinWindow && itemsMatch) reason = 'same_order_within_30min';
  else if (withinWindow && !itemsMatch) reason = 'different_order_within_30min';
  else if (!withinWindow && itemsMatch) reason = 'same_order_after_30min';
}

return [{
  json: {
    isDuplicate,
    reason,
    itemsMatch,
    itemsMissing,
    itemsParsedOk,
    minutesSinceLastOrder: Math.round(minutesSinceLastOrder),
    lastOrderId: newest.orderId,
    lastOrderItems: newest.items,
    lastOrderTotal: newest.totalAmount,
    lastOrderStatus: newest.status
  }
}];

const trigger = $('When Executed by Another Workflow').first().json;

function parseItems(raw) {
  if (Array.isArray(raw)) return raw;
  if (raw && typeof raw === 'object') return raw;
  if (typeof raw === 'string' && raw.trim()) {
    try { return JSON.parse(raw); } catch (e) { return []; }
  }
  return [];
}

const items = parseItems(trigger.items);
const total = parseFloat(trigger.total);

const validItems = Array.isArray(items) && items.length > 0 &&
  items.every(i => i && typeof i.name === 'string' && i.name.trim().length > 0);
const validTotal = !isNaN(total) && total > 0;

return [{ json: { valid: validItems && validTotal } }];

function normalizeItems(raw) {
  let arr = raw;
  if (typeof arr === 'string') { try { arr = JSON.parse(arr); } catch (e) { arr = []; } }
  if (!Array.isArray(arr)) arr = [];
  return arr.filter(i => i && i.name).map(i => {
    const out = { name: String(i.name), qty: Number(i.qty || 1) };
    const price = Number(i.price);
    if (i.price !== undefined && i.price !== null && i.price !== '' && isFinite(price)) out.price = price;
    return out;
  });
}

// Data sources:
//   $('When Executed by Another Workflow').first().json -> phone, items (JSON string), total, address
//   $('Find Duplicate').first().json -> reason
const t = $('When Executed by Another Workflow').first().json;
const total = Number(t.total);

return [{ json: {
  phone: String(t.phone),
  pendingOrderPayload: {
    items: normalizeItems(t.items),
    total: isFinite(total) ? total : String(t.total),
    address: t.address || ''
  },
  reason: $('Find Duplicate').first().json.reason,
  timestamp: new Date().toISOString(),
  awaitingConfirmation: true,
  workflowName: $workflow.name,
  workflowId: $workflow.id,
  executionId: $execution.id
} }];
